/* 
the vega tooltip won't pick up spectrum variables
set all the default styling
*/
#vg-tooltip-element.vg-tooltip {
  border-radius: 8px;
  font-family: adobe-clean, sans-serif;
  font-size: 14px;
  font-style: normal;
  font-weight: 400;
  line-height: 21px;
  padding: 12px;
  max-width: 300px;
}
/*
sections sometimes add a 500ms transition but vega tooltips close instantly
this removes transitions in the vega tooltip
*/
#vg-tooltip-element.vg-tooltip section {
  transition: none;
}
/* double scope light-theme so that it has higher precedence */
#vg-tooltip-element.vg-tooltip.light-theme.light-theme {
  background-color: #fff;
  color: #292929;
  border: 1px solid #e1e1e1;
  box-shadow: 0 0 2px 0 rgba(0, 0, 0, 0.12), 0 2px 6px 0 rgba(0, 0, 0, 0.04), 0 4px 12px 0 rgba(0, 0, 0, 0.08);
}
/* double scope dark-theme so that it has higher precedence */
#vg-tooltip-element.vg-tooltip.dark-theme.dark-theme {
  background-color: #111111;
  color: #dbdbdb;
  border: 1px solid #323232;
  box-shadow: 0 0 2px 0 rgba(0, 0, 0, 0.24), 0 2px 6px 0 rgba(0, 0, 0, 0.08), 0 4px 12px 0 rgba(0, 0, 0, 0.16);
}
#vg-tooltip-element.vg-tooltip .legend-tooltip {
  max-width: 150px;
}
#vg-tooltip-element.vg-tooltip .legend-tooltip .series {
  font-weight: 700;
}
#vg-tooltip-element.vg-tooltip .legend-tooltip .series-description {
  margin: 0px;
}
/*
  Popover style overrides — match the S2 elevated/tooltip style.
  .rsc-popover is applied via UNSAFE_className on the Dialog in RscChart.tsx.
  S2 Dialog styles are in @layer so un-layered rules here take precedence.
*/
.rsc-popover {
  outline: none;
  border: 1px solid #e1e1e1;
  box-shadow: 0 0 2px 0 rgba(0, 0, 0, 0.12), 0 2px 6px 0 rgba(0, 0, 0, 0.04), 0 4px 12px 0 rgba(0, 0, 0, 0.08);
}
.spectrum--dark .rsc-popover {
  border-color: #323232;
}
/*
  Typography for popover content. Matches the tooltip font settings.
*/
.rsc-popover-content {
  font-family: adobe-clean, sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.5;
}
.rsc-donut-dialog-content {
  display: grid;
  grid-template-columns: 16px minmax(0, auto);
  align-items: center;
  column-gap: 8px;
  row-gap: 4px;
}
.rsc-donut-dialog-swatch {
  width: 16px;
  height: 16px;
  border-radius: 4px;
}
.rsc-donut-dialog-series {
  min-width: 0;
  overflow-wrap: anywhere;
  color: #505050;
}
.spectrum--dark .rsc-donut-dialog-series,
#vg-tooltip-element.vg-tooltip.dark-theme .rsc-donut-dialog-series {
  color: #afafaf;
}
.rsc-donut-dialog-percent-value {
  grid-column: 1 / -1;
  font-weight: 800;
}
/* Collapse the S2 Dialog's default min-height so the action bar fits its content tightly.
   S2 component styles are in @layer, so un-layered rules here take precedence without !important. */
.rsc-action-bar {
  min-block-size: 0;
  max-inline-size: 800px;
  margin: 0;
  padding: 0;
  background: none;
  color: inherit;
}
.rsc-action-bar-drag-handle {
  appearance: none;
  width: 4px;
  align-self: stretch;
  min-block-size: 20px;
  padding: 0;
  background-color: var(--spectrum-gray-500, #b3b3b3);
  border: 0;
  border-radius: 2px;
  cursor: grab;
  flex-shrink: 0;
  touch-action: none;
}
.rsc-action-bar-drag-handle:active {
  cursor: grabbing;
}
.rsc-action-bar--emphasized {
  background-color: var(--spectrum-accent-background-color-default, #0d66d0);
  border-color: transparent;
}
.rsc-action-bar--emphasized .rsc-action-bar-drag-handle {
  background-color: rgba(255, 255, 255, 0.5);
}
.rsc-action-bar-overflow {
  display: flex;
  flex-direction: column;
  padding: 4px;
  white-space: nowrap;
}
.rsc-container {
  position: relative;
  width: auto;
  height: 100%;
}
