import {
  BarAnnotationOptions,
  ChartActionBarOptions,
  ChartPopoverOptions,
  ChartInspectOptions,
  ColorFacet,
  ColorScheme,
  DonutSummaryOptions,
  HighlightedItem,
  InteractionMode,
  LineType,
  LineTypeFacet,
  LineWidthFacet,
  MetricRangeOptions,
  OpacityFacet,
  ScaleType,
  ScatterPathOptions,
  SegmentLabelOptions,
  TrendlineOptions,
  InterpolationType,
  LineCap,
} from '../types/index.js';

export const getPopoverMarkName = (
  chartPopovers: ChartPopoverOptions[],
  lineName: string,
  chartActionBars?: ChartActionBarOptions[]
): string | undefined => {
  if (chartPopovers.length || chartActionBars?.length) {
    return lineName;
  }
};

/**
 * Checks if the line chart is a dual metric axis chart
 * @param options - The line chart options
 * @returns True if the line chart is a dual metric axis chart, false otherwise
 */
export const isDualMetricAxis = (options: { dualMetricAxis?: boolean }): boolean => {
  return Boolean(options.dualMetricAxis);
};

export interface LineMarkOptions {
  barAnnotations?: BarAnnotationOptions[];
  chartActionBars?: ChartActionBarOptions[];
  chartPopovers?: ChartPopoverOptions[];
  chartInspects?: ChartInspectOptions[];
  color: ColorFacet;
  colorScheme: ColorScheme;
  comboSiblingNames?: string[];
  dimension: string;
  displayOnHover?: boolean;
  donutSummaries?: DonutSummaryOptions[];
  dualMetricAxis?: boolean;
  gradient?: boolean;
  hasOnClick?: boolean;
  highlightedItem?: HighlightedItem;
  idKey: string;
  interactiveMarkName?: string; // optional name of the mark that is used for hover and click interactions
  interactionMode?: InteractionMode;
  isHighlightedByDimension?: boolean;
  isHighlightedByGroup?: boolean;
  lineCap?: LineCap;
  lineType: LineTypeFacet;
  lineWidth?: LineWidthFacet;
  metric: string;
  metricAxis?: string;
  metricRanges?: MetricRangeOptions[];
  name: string;
  opacity: OpacityFacet;
  pointSize?: number;
  popoverMarkName?: string;
  scaleType: ScaleType;
  scatterPaths?: ScatterPathOptions[];
  segmentLabels?: SegmentLabelOptions[];
  dimensionHover?: boolean;
  hoverLabelKey?: string;
  showHoverLabel?: boolean;
  staticPoint?: string;
  trendlines?: TrendlineOptions[];
  interpolate?: InterpolationType;
  alternateSegmentKey?: string;
  alternateSegmentLineType?: LineType;
  alternateSegmentLabel?: string;
  primarySeries?: number | string[];
  otherSeriesColor?: string;
  isHoverAnimate?: boolean;
  isDrawInAnimate?: boolean;
}
