import { FC, Ref, useEffect, useId, useMemo, useRef, useState } from 'react';

import { View } from 'vega';

import { Provider } from '@react-spectrum/s2';
import { getColorValue } from '@spectrum-charts/core-s2/tokens';
import { ChartData, ChartHandle } from '@spectrum-charts/vega-spec-builder-s2';

import './Chart.css';
import { RscChart } from './RscChart.js';
import { applyChartPropsDefaults, resolveAnimations } from './chartUtils.js';
import { EmptyState } from './components/index.js';
import { LoadingState } from './components/LoadingState/index.js';
import { ChartProvider } from './context/RscChartContext.js';
import useChartHeight from './hooks/useChartHeight.js';
import useChartImperativeHandle from './hooks/useChartImperativeHandle.js';
import usePrefersReducedMotion from './hooks/usePrefersReducedMotion.js';
import useChartWidth from './hooks/useChartWidth.js';
import { useResizeObserver } from './hooks/useResizeObserver.js';
import { ChartProps, RscChartProps } from './types/index.js';

interface PlaceholderContentProps {
  data: ChartData[];
  loading?: boolean;
  height?: number;
  emptyStateText: string;
}

export const Chart = ({ ref, ...props }: ChartProps & { ref?: Ref<ChartHandle> }) => {
  const {
    backgroundColor,
    colorScheme,
    data,
    dataTestId,
    emptyStateText,
    height,
    loading,
    maxHeight,
    maxWidth,
    minHeight,
    minWidth,
    onVegaViewReady,
    title,
    UNSAFE_vegaSpec,
    width,
    ...otherProps
  } = applyChartPropsDefaults(props);

  // useId is stable across server and client renders; colons are stripped since chartId is used in unescaped CSS id selectors elsewhere
  const chartId = `rsc-${useId().replace(/:/g, '')}`;
  // The view returned by vega. This is above RscChart so it can be used for downloading and copying to clipboard.
  const chartView = useRef<View | undefined>(undefined);
  const [containerWidth, setContainerWidth] = useState<number>(0);
  const [containerHeight, setContainerHeight] = useState<number>(0);
  const prefersReducedMotion = usePrefersReducedMotion();

  useChartImperativeHandle(ref, { chartView, title });

  const containerRef = useResizeObserver<HTMLDivElement>((_target, entry) => {
    if (typeof width !== 'number') {
      setContainerWidth(entry.contentRect.width);
    }

    if (typeof height !== 'number') {
      setContainerHeight(entry.contentRect.height);
    }
  });
  const chartWidth = useChartWidth(containerWidth, maxWidth, minWidth, width); // calculates the width the vega chart should be
  const chartHeight = useChartHeight(containerHeight, maxHeight, minHeight, height); // calculates the height the vega chart should be

  const showPlaceholderContent = useMemo(() => Boolean(loading ?? !data.length), [loading, data]);

  useEffect(() => {
    // if placeholder content is displayed, clear out the chartview so it can't be downloaded or copied to clipboard
    if (showPlaceholderContent) {
      chartView.current = undefined;
    }
  }, [showPlaceholderContent]);

  if (props.children && UNSAFE_vegaSpec) {
    throw new Error('Chart cannot accept both children and `UNSAFE_vegaSpec` prop. Please choose one or the other.');
  }

  // Chart requires children or a Vega spec to configure what is drawn. If there aren't any children or a Vega spec, throw an error and return a fragment.
  if (!props.children && !UNSAFE_vegaSpec) {
    throw new Error(
      'No children in the <Chart/> component. Chart is a collection components and requires children to draw correctly.'
    );
  }

  const rscChartProps: RscChartProps = {
    data,
    backgroundColor,
    colorScheme,
    title,
    chartWidth,
    chartHeight,
    UNSAFE_vegaSpec,
    onVegaViewReady,
    ...otherProps,
    animations: resolveAnimations(otherProps.animations, prefersReducedMotion),
  };

  const chartContent = <RscChart {...rscChartProps}>{props.children}</RscChart>;

  return (
    <Provider
      colorScheme={colorScheme}
      UNSAFE_style={{ backgroundColor: 'transparent', height: '100%' }}
    >
      <div ref={containerRef} id={chartId} data-testid={dataTestId} className="rsc-container">
        <div style={{ backgroundColor: getColorValue(backgroundColor, colorScheme) }}>
          {showPlaceholderContent ? (
            <PlaceholderContent loading={loading} data={data} height={chartHeight} emptyStateText={emptyStateText} />
          ) : (
            <ChartProvider chartId={chartId} chartView={chartView}>
              {chartContent}
            </ChartProvider>
          )}
        </div>
      </div>
    </Provider>
  );
};
Chart.displayName = 'Chart';

const PlaceholderContent: FC<PlaceholderContentProps> = ({ data, emptyStateText, loading, ...layoutProps }) => {
  if (loading) {
    //show a spinner while data is loading
    return <LoadingState {...layoutProps} />;
  } else if (!data.length) {
    //if it is no longer loading but there is not data, show the empty state
    return <EmptyState {...layoutProps} text={emptyStateText} />;
  }
  return <></>;
};
