import { RefObject, ReactNode, createContext, useContext, useMemo, useRef, useState } from 'react';

import { Signal, View } from 'vega';

import { Datum, MarkBounds } from '@spectrum-charts/vega-spec-builder-s2';

interface HoveredAxisLabel {
  bounds: MarkBounds;
  content: string;
}

interface ChartContextValue {
  // Chart view state
  chartView: RefObject<View | undefined>;
  chartId: string;

  // Selection state
  selectedData: RefObject<Datum | null>;
  selectedDataName: RefObject<string>;
  selectedDataBounds: RefObject<MarkBounds>;

  // Set when Space opens a popover, so its close handler can skip clearing hover-parity signals keyboard focus still owns.
  keyboardPopoverComponentName: RefObject<string | null>;

  // Popover state
  isPopoverOpen: boolean;
  setIsPopoverOpen: (isOpen: boolean) => void;
  popoverAnchorRef: RefObject<HTMLDivElement | null>;

  // Axis label tooltip state
  hoveredAxisLabel: HoveredAxisLabel | null;
  setHoveredAxisLabel: (hoveredAxisLabel: HoveredAxisLabel | null) => void;

  // Spec state
  controlledHoveredIdSignal: RefObject<Signal | undefined>;
  controlledHoveredGroupSignal: RefObject<Signal | undefined>;
}

const ChartContext = createContext<ChartContextValue | null>(null);

interface ChartProviderProps {
  children: ReactNode;
  chartId: string;
  chartView: RefObject<View | undefined>;
}

export const ChartProvider = ({ children, chartId, chartView }: ChartProviderProps) => {
  const controlledHoveredIdSignal = useRef<Signal | undefined>(undefined);
  const controlledHoveredGroupSignal = useRef<Signal | undefined>(undefined);
  const popoverAnchorRef = useRef<HTMLDivElement | null>(null);
  const selectedData = useRef<Datum | null>(null);
  const selectedDataName = useRef<string>('');
  const selectedDataBounds = useRef<MarkBounds>({ x1: 0, x2: 0, y1: 0, y2: 0 });
  const keyboardPopoverComponentName = useRef<string | null>(null);

  const [isPopoverOpen, setIsPopoverOpen] = useState(false);
  const [hoveredAxisLabel, setHoveredAxisLabel] = useState<HoveredAxisLabel | null>(null);

  const value: ChartContextValue = useMemo(
    () => ({
      chartView,
      chartId,
      selectedData,
      selectedDataName,
      selectedDataBounds,
      keyboardPopoverComponentName,
      controlledHoveredIdSignal,
      controlledHoveredGroupSignal,
      isPopoverOpen,
      setIsPopoverOpen,
      popoverAnchorRef,
      hoveredAxisLabel,
      setHoveredAxisLabel,
    }),
    [chartId, chartView, isPopoverOpen, hoveredAxisLabel]
  );

  return <ChartContext.Provider value={value}>{children}</ChartContext.Provider>;
};

export const useChartContext = () => {
  const context = useContext(ChartContext);
  if (!context) {
    throw new Error('useChartContext must be used within a ChartProvider');
  }
  return context;
};
